+  --color-accent-dk: #4238b0;
+  --color-accent-bg: #f0eeff;
+  --color-header-bg: #1a1917;
+  --color-header-fg: #ffffff;
+
+  --radius-sm: 6px;
+  --radius-md: 12px;
+  --radius-lg: 16px;
+
