+}
+.logo { font-size: 1.5rem; }
+.site-name { font-size: 1.125rem; font-weight: 700; letter-spacing: -.01em; }
+
+/* ─── Hero ──────────────────────────────────────────────────────── */
+.hero {
+  max-width: 760px;
+  margin: 0 auto;
+  padding: 3rem 1.5rem 2rem;
+}
