+  font-size: clamp(1.75rem, 5vw, 2.5rem);
+  font-weight: 800;
+  letter-spacing: -.03em;
+  line-height: 1.15;
+}
+.hero-sub {
+  margin-top: .5rem;
+  font-size: 1.125rem;
+  color: var(--color-text-mute);
+}
+
+/* ─── FAQ container ─────────────────────────────────────────────── */
+.faq-container {
+  max-width: 760px;
+  margin: 0 auto;
+  padding: 0 1.5rem 4rem;
+  display: flex;
+  flex-direction: column;
+  gap: 2.5rem;
+}
+
+/* ─── Section heading ───────────────────────────────────────────── */
+.faq-container section > h2 {
+  font-size: .75rem;
+  font-weight: 700;
+  letter-spacing: .1em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+  margin-bottom: 1rem;
+}
+
+/* ─── FAQ card (.example) ───────────────────────────────────────── */
+.example {
+  background: var(--color-surface);
