+  transition: box-shadow var(--transition);
+  overflow: hidden;
+}
+.example + .example { margin-top: .75rem; }
+.example:has(.faq-trigger[aria-expanded="true"]) { box-shadow: var(--shadow-card-hover); }
+
+/* Question heading — remove default margin */
+.example h3 { font-size: 1rem; font-weight: inherit; }
+
+/* ─── Trigger button ────────────────────────────────────────────── */
+.faq-trigger {
