+  border: none;
+  cursor: pointer;
+  font-size: 1rem;
+  font-weight: 600;
+  color: var(--color-text);
+  text-align: left;
+  line-height: 1.4;
+  border-radius: var(--radius-md);
+  transition: background var(--transition), color var(--transition);
+}
+.faq-trigger:hover { background: var(--color-accent-bg); color: var(--color-accent-dk); }
+.faq-trigger:focus-visible {
+  outline: 3px solid var(--color-accent);
+  outline-offset: -3px;
