  'aria-expanded on buttons': (html.match(/aria-expanded=\"true\"/g)||[]).length === 9,
  '.details panels': (html.match(/class=\"details\"/g)||[]).length === 9,
  '.example wrappers': (html.match(/class=\"example\"/g)||[]).length === 9,
  'no aria-expanded on non-buttons': !html.match(/<div[^>]+aria-expanded/),
  'h3 wraps triggers': (html.match(/<h3>/g)||[]).length === 9,
  'sections labelled': (html.match(/aria-labelledby/g)||[]).length === 3,
  'footer present': html.includes('<footer'),
  'header present': html.includes('<header'),
};
